import React from 'react';
import classNames from 'classnames';
import { _t } from '../../../languageHandler';

const ExternalLink: React.FC<React.AnchorHTMLAttributes<HTMLAnchorElement>> = ({
    className, children, target = '_blank', rel = 'noreferrer noopener', ...props
}) => (
    <a {...props} target={target} rel={rel} className={classNames('mx_ExternalLink', className)}>
        { children }
        <span className="mx_ExternalLink_icon" aria-hidden="true" />
        { target === '_blank' &&
            <span className="mx_ExternalLink_newTab">{ _t('Opens in a new tab') }</span> }
    </a>
);

export default ExternalLink;
